const completeTaskDB=[{"s":"Aliado es quien sigue diciendo que sí cuando cambia el ___.","opts":["director","tema","horario"],"ans":"director"},{"s":"Lo que no está en el ___ no pasó.","opts":["acta","correo","plan"],"ans":"acta"},{"s":"Al entusiasta se le pide una cosa concreta y con ___.","opts":["fecha","precio","testigo"],"ans":"fecha"},{"s":"El patronato es la junta ___ de la comunidad.","opts":["directiva","escolar","municipal"],"ans":"directiva"},{"s":"El aliado de ___ es el más escaso.","opts":["manos","nombre","dinero"],"ans":"manos"},{"s":"Toda alianza se prueba en ___.","opts":["pequeno","publico","grupo"],"ans":"pequeno"},{"s":"Hacen falta dos personas enteradas por cada ___.","opts":["lado","mes","centro"],"ans":"lado"},{"s":"De la foto se sale, del ___ no.","opts":["acta","grupo","trato"],"ans":"acta"}];
const explainQuestions=[{"q":"Explica por qué una alianza es un acuerdo entre personas y qué consecuencia tiene eso.","ans":"Porque quien dice que sí es siempre una persona concreta, y las personas se van: la directora se traslada, el regidor pierde las elecciones, el presidente del patronato termina su periodo. Las instituciones siguen ahí, pero el acuerdo estaba en la cabeza de quien lo hizo. La consecuencia práctica es que la prueba de una alianza no es lo bien que va hoy, sino si sigue en pie cuando cambia el director. Y de ahí sale la señal de alarma de la etapa: cuando la alianza solo existe en la cabeza de dos personas, no hay alianza, hay una amistad útil. Es una cosa estupenda y se acaba el día que esa persona se va, sin que nadie haya hecho nada mal, que es lo que la hace difícil de ver a tiempo."},{"q":"¿Qué es la regla del acta y por qué pedirla no ofende a nadie?","ans":"La regla del acta dice que, en un patronato, lo que no está escrito en el libro no pasó. No es desconfianza hacia la persona que ofrece: es cómo funciona esa institución con todo lo demás, desde una compra hasta un permiso. Pedir un punto de acta es pedir un trámite, no un favor, y se dice con esas palabras: «¿lo pueden poner como punto en la próxima reunión?». Lo que se gana es enorme para el trabajo que cuesta: media línea en el libro hace que el acuerdo sobreviva al cambio de junta directiva, que en Honduras ocurre cada dos años. Y hay un beneficio menos evidente: al pasar por la junta, el acuerdo deja de ser del presidente y pasa a ser del patronato, con lo cual más gente lo defiende."},{"q":"Di cuáles son los cuatro tipos de aliado y cómo se reconoce al que no lo es.","ans":"El de acceso te abre una puerta cerrada: una directora, un presidente de patronato. El de manos trabaja contigo, y es el más escaso y el que menos se agradece: la maestra que prueba las fichas, el joven que ayuda a imprimir. El de dinero pone recursos o materiales. El de nombre te hace creíble en dos minutos, y por eso mismo es el que más caro sale si sale mal. El quinto no es aliado: el entusiasta, que dice que sí a todo, no aporta nada concreto y ocupa el sitio de uno real, que es el daño de verdad. Se reconoce con una prueba de cinco segundos: se le pide una cosa pequeña con fecha, «¿me consigues el salón para el sábado 12?». El aliado contesta sí o no; el entusiasta contesta «claro, hablamos», y esa frase se repite hasta que se acaba el año."},{"q":"Explica qué puede y qué no puede el patronato, y por qué conviene saberlo.","ans":"Puede ceder el salón comunal, convocar a los vecinos, respaldar una solicitud ante la alcaldía y poner un acuerdo en acta. No puede decidir lo que pasa dentro de la escuela, que es de la dirección y la supervisión, ni comprometer dinero público. Y ningún directivo, ni siquiera el presidente, puede acordar solo lo que la junta no ha visto: si lo hace, el acuerdo dura lo que dure él en el cargo. Conviene saberlo por dos razones. Primero, para no pedir lo que no pueden dar, que hace perder tiempo y credibilidad. Y segundo, para saber a quién hay que llevar cada cosa: un permiso de aula se pide a la dirección, un salón comunal al patronato y un permiso municipal a la alcaldía por escrito."},{"q":"¿Qué es el relevo de una alianza y qué tres cosas hacen falta para que exista?","ans":"El relevo es que la alianza sobreviva a las personas que la hicieron. Hacen falta tres cosas concretas y ninguna es cara. La primera, que esté en un papel: un acta, una carta con sello, un mensaje guardado con fecha; media página basta. La segunda, que la conozcan al menos dos personas por cada lado, para que la información no se vaya con quien se va. Y la tercera, que tenga una fecha de renovación, para que alguien tenga que acordarse de ella antes de que caduque. Sin las tres, lo que hay es una relación buena mientras dure, y en un centro educativo hondureño los traslados no avisan. El día que trasladan a la directora, un proyecto con relevo cambia de interlocutor; uno sin relevo empieza de cero, y encima parece «cosa de la anterior»."},{"q":"Explica cómo se trabaja con la comunidad y qué regla no se puede saltar.","ans":"Se empieza con algo útil y sin pedir nada: un taller para padres, una hoja que sirva, algo que se pueda usar el lunes. La comunidad (padres organizados, patronato, iglesia y comercio pequeño) no sale en ningún organigrama y puede parar o empujar cualquier cosa, así que tratarla como público y no como aliado es el error más caro de esta etapa. La regla que no se puede saltar es la de la asamblea: lo que se anuncia en público se cumple en público, así que no se anuncia nada que no esté seguro. Una promesa incumplida en una asamblea tarda años en olvidarse y no se arregla con explicaciones. Y para el entusiasmo hay una regla práctica: se traduce en tres tareas concretas con nombre y fecha en la misma reunión, porque el entusiasmo sin tarea se apaga en tres semanas, siempre."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

