const timelineData=[{"y":"1","icon":"🎁","label":"El aporte","text":"Qué pone cada uno, <strong>en cosas concretas</strong> y no en intenciones. <strong>Si falta:</strong> cada uno espera del otro algo distinto. <strong>En M.E.T.A.S:</strong> el patronato pone salón, el proyecto pone taller."},{"y":"2","icon":"🤲","label":"La ganancia","text":"Qué gana el otro, <strong>dicho con sus palabras</strong>. <strong>Si falta:</strong> la alianza se apoya en una suposición. <strong>Ejemplo:</strong> un patronato gana actividad y algo que enseñar en la asamblea."},{"y":"3","icon":"✍️","label":"La firma","text":"Quién puede <strong>comprometer a su institución</strong> de verdad. <strong>Si falta:</strong> el acuerdo dura lo que dure esa persona. <strong>En un patronato:</strong> la junta, no el presidente solo."},{"y":"4","icon":"📖","label":"El papel","text":"Dónde queda escrito: <strong>acta, carta con sello o mensaje guardado</strong>. <strong>Si falta:</strong> lo que no está en el acta no pasó. <strong>Basta con:</strong> media página con fecha."},{"y":"5","icon":"📅","label":"El plazo","text":"Hasta cuándo dura y <strong>cuándo se vuelve a hablar</strong>. <strong>Si falta:</strong> la alianza se va apagando sin que nadie la dé por terminada. <strong>Sirve para:</strong> obligar a acordarse."},{"y":"6","icon":"🚪","label":"La salida","text":"Qué pasa si se rompe y <strong>cómo se termina sin pelea</strong>. <strong>Si falta:</strong> el final deja resentimiento en una comunidad donde todos se ven. <strong>Se dice al principio</strong>, que es cuando no duele."},{"y":"7","icon":"🔄","label":"El relevo","text":"Que sobreviva al <strong>cambio de personas</strong>. <strong>Cómo:</strong> papel, dos enterados por cada lado y fecha de renovación. <strong>Si falta:</strong> se empieza de cero cada traslado."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

